"use client"

import {
  Alert02Icon,
  Archive02Icon,
  ArrowDataTransferVerticalIcon,
  ArrowDown01Icon,
  ArrowDownLeft01Icon,
  ArrowLeft01Icon,
  ArrowRight01Icon,
  ArrowUp01Icon,
  ArrowUpRight01Icon,
  BookOpen02Icon,
  Building02Icon,
  CallOutgoing01Icon,
  BubbleChatIcon,
  Calendar03Icon,
  Cancel01Icon,
  CancelCircleIcon,
  CheckmarkCircle02Icon,
  Clock01Icon,
  Coins01Icon,
  ColorsIcon,
  ComponentIcon,
  Copy01Icon,
  CopyLinkIcon as CopyLinkGlyph,
  CpuIcon,
  CubeIcon,
  DashboardSquare01Icon,
  Delete02Icon,
  Download01Icon,
  EaseCurveControlPointsIcon,
  FileValidationIcon,
  FilterIcon,
  Home01Icon,
  InformationCircleIcon,
  MoreHorizontalIcon,
  PencilEdit02Icon,
  PlayIcon,
  PlusSignIcon,
  RefreshIcon,
  Robot01Icon,
  Search01Icon,
  SearchRemoveIcon,
  Tick02Icon,
  GlobalIcon,
  File01Icon,
  TextIcon,
  FolderAddIcon,
  FolderSyncIcon,
  ArrowLeft02Icon,
  ArrowRight02Icon,
  BankIcon,
  DashedLineCircleIcon,
  Hospital01Icon,
  RealEstate01Icon,
  Restaurant01Icon,
  ShoppingBag01Icon,
  SmartPhone01Icon,
  SparklesIcon,
  AlertCircleIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/* The icon rule's example: ordinary actions, because the point of that card is
   one size and one stroke weight rather than the glyphs themselves. */
export const PreviewIcon = icon(PlayIcon, "PreviewIcon")
export const NarrowIcon = icon(FilterIcon, "NarrowIcon")
export const ExportIcon = icon(Download01Icon, "ExportIcon")
export const DeleteIcon = icon(Delete02Icon, "DeleteIcon")

/** The two a row carries. Named for the row, not for the glyph. */
export const EditRowIcon = icon(PencilEdit02Icon, "EditRowIcon")

/** Sorting: the active direction, and the affordance on a column that is not sorted. */
export const SortAscIcon = icon(ArrowUp01Icon, "SortAscIcon")
export const SortDescIcon = icon(ArrowDown01Icon, "SortDescIcon")
export const SortableIcon = icon(ArrowDataTransferVerticalIcon, "SortableIcon")

/** Direction, which is what tells the two neutral chips apart. */
export const InboundIcon = icon(ArrowDownLeft01Icon, "InboundIcon")
export const OutboundIcon = icon(ArrowUpRight01Icon, "OutboundIcon")

/** The four call states. */
export const CompletedIcon = icon(CheckmarkCircle02Icon, "CompletedIcon")
export const FailedIcon = icon(CancelCircleIcon, "FailedIcon")
export const RunningIcon = icon(Clock01Icon, "RunningIcon")
export const ScheduledIcon = icon(Calendar03Icon, "ScheduledIcon")

/* The close control on the drawer demo's header — the house shape is a title,
   a description and this button, with no icon tile beside the title. */
export const CloseIcon = icon(Cancel01Icon, "CloseIcon")

export const RowMenuIcon = icon(MoreHorizontalIcon, "RowMenuIcon")
export const SearchIcon = icon(Search01Icon, "SearchIcon")

/* The multi-step form explains its fields with an (i) beside the label rather
   than a line under it — the reference it is built from does, and a screen
   uses one language for all of its fields or the other. */
export const HintIcon = icon(InformationCircleIcon, "HintIcon")
export const WarningIcon = icon(Alert02Icon, "WarningIcon")

/** A bare tick, for a step already done. `CompletedIcon` is a circled one and
    would sit inside the stepper's own circle. */
export const StepDoneIcon = icon(Tick02Icon, "StepDoneIcon")

/* The rail's disclosure chevron. It points down when the section is open and
   is rotated a quarter turn when it is not, so one glyph carries both states
   rather than two glyphs that have to be told apart. */
export const SectionToggleIcon = icon(ArrowDown01Icon, "SectionToggleIcon")

/* The tabs demo. One glyph per view of the same call, each naming what that
   view holds — the bar is the thing being demonstrated, so the labels carry
   an icon the way a real settings or record bar does. */
export const TranscriptIcon = icon(BubbleChatIcon, "TranscriptIcon")
export const ModelIcon = icon(CpuIcon, "ModelIcon")
export const CostIcon = icon(Coins01Icon, "CostIcon")

/* The header control that hands this exact topic to someone. The tick is the
   same glyph a finished step uses — one "done" mark across the reference,
   rather than a second one that has to be learned. */
export const CopyLinkIcon = icon(CopyLinkGlyph, "CopyLinkIcon")
export const CopiedIcon = icon(Tick02Icon, "CopiedIcon")

/* Copies a whole section out as a skill file. */
export const CopySkillIcon = icon(Copy01Icon, "CopySkillIcon")

/* The three states that are not the populated one, each named for the state
   rather than the glyph: nothing here yet, nothing matched, and it broke. */
export const NoResultsIcon = icon(SearchRemoveIcon, "NoResultsIcon")
export const SourceIcon = icon(BookOpen02Icon, "SourceIcon")
export const RetryIcon = icon(RefreshIcon, "RetryIcon")

/* The ring's way back up a level: from one section's topics to the five
   sections themselves. Named for where it goes rather than for the arrow,
   because the same glyph points back to two different places on this page. */
export const AllSectionsIcon = icon(ArrowLeft01Icon, "AllSectionsIcon")

/** The trailing mark on a section row on the overview. */
export const OpenSectionIcon = icon(ArrowRight01Icon, "OpenSectionIcon")

/* One per section on the overview. Named for the shelf, not the glyph, and
   present for the reason the house rules allow an icon in a list at all: five
   cards that differ only by a word are quicker to tell apart with a mark than
   without one. Nothing else on that page carries an icon. */
export const FoundationsIcon = icon(ColorsIcon, "FoundationsIcon")
export const MotionSectionIcon = icon(
  EaseCurveControlPointsIcon,
  "MotionSectionIcon",
)
export const PatternsIcon = icon(DashboardSquare01Icon, "PatternsIcon")
export const CustomComponentsIcon = icon(CubeIcon, "CustomComponentsIcon")
export const ShadcnComponentsIcon = icon(ComponentIcon, "ShadcnComponentsIcon")

/* The Icons tile's subject: one everyday glyph from the set the product draws
   from, set on its construction sheet by the tile's drawing. */
export const IconsTopicGlyph = icon(Home01Icon, "IconsTopicGlyph")

/* The index-page demo's header action. */
export const StartCallIcon = icon(CallOutgoing01Icon, "StartCallIcon")

/* The scenarios index: its two header tiles, the admin scope, and the row's
   one icon action. */
export const CreateScenarioIcon = icon(PlusSignIcon, "CreateScenarioIcon")
export const PlaygroundIcon = icon(Robot01Icon, "PlaygroundIcon")
export const OrganisationIcon = icon(Building02Icon, "OrganisationIcon")
export const CreateTemplateIcon = icon(FileValidationIcon, "CreateTemplateIcon")
export const ActiveIcon = icon(CheckmarkCircle02Icon, "ActiveIcon")
export const DeletedIcon = icon(Delete02Icon, "DeletedIcon")

/* The knowledge base's five ways in, as its header tiles. */
export const AddUrlIcon = icon(GlobalIcon, "AddUrlIcon")
export const AddFilesIcon = icon(File01Icon, "AddFilesIcon")
export const AddTextIcon = icon(TextIcon, "AddTextIcon")
export const CreateFolderIcon = icon(FolderAddIcon, "CreateFolderIcon")
export const SyncDocumentsIcon = icon(FolderSyncIcon, "SyncDocumentsIcon")

/* Surfaces: the demos under Components › Choosing a surface. */
export const ArchiveIcon = icon(Archive02Icon, "ArchiveIcon")
export const PreviousRecordIcon = icon(ArrowUp01Icon, "PreviousRecordIcon")
export const NextRecordIcon = icon(ArrowDown01Icon, "NextRecordIcon")
export const CreateInListIcon = icon(PlusSignIcon, "CreateInListIcon")
export const CopyKeyIcon = icon(Copy01Icon, "CopyKeyIcon")

/* Creation flow: the ways to start a scenario, and the industries its
   templates are filed under. */
export const StartBlankIcon = icon(DashedLineCircleIcon, "StartBlankIcon")
export const ChooseStartIcon = icon(ArrowRight02Icon, "ChooseStartIcon")
export const StepBackIcon = icon(ArrowLeft02Icon, "StepBackIcon")
export const BuildWithAiIcon = icon(SparklesIcon, "BuildWithAiIcon")
export const HealthcareIcon = icon(Hospital01Icon, "HealthcareIcon")
export const TelecomIcon = icon(SmartPhone01Icon, "TelecomIcon")
export const BankingIcon = icon(BankIcon, "BankingIcon")
export const RestaurantsIcon = icon(Restaurant01Icon, "RestaurantsIcon")
export const RetailIcon = icon(ShoppingBag01Icon, "RetailIcon")
export const RealEstateIcon = icon(RealEstate01Icon, "RealEstateIcon")

/* JSON: the fold toggle on an object's opening line, and copy. */
export const FoldIcon = icon(ArrowRight01Icon, "FoldIcon")
export const CopyJsonIcon = icon(Copy01Icon, "CopyJsonIcon")

/* Alerts: the error intent's glyph. Neutral, success and warning reuse
   HintIcon, CompletedIcon and WarningIcon. */
export const ErrorAlertIcon = icon(AlertCircleIcon, "ErrorAlertIcon")

"use client"

import * as React from "react"
import { toast } from "sonner"

import {
  CopiedIcon,
  CopyJsonIcon,
  FoldIcon,
} from "@/components/design-system/icons"
import { SecondaryTabs } from "@/components/design-system/tabs-preview"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { TabsContent } from "@/components/ui/tabs"
import { cn } from "@/lib/utils"

/**
 * JSON, read rather than dumped.
 *
 * The admin's global settings page prints each language as
 * `JSON.stringify(settings, null, 2)` in a `<pre>`, two cards side by side.
 * They are fifty lines each and mostly identical, so the one thing the reader
 * came for — what differs between English and Arabic — is the thing the page
 * makes hardest to see.
 *
 * Monochrome, in the Unsaved changes diff's register: a bordered block, small
 * mono type, what is shared muted and what differs at full strength. No tint
 * marks a difference — two languages are peers, not a before and an after, so
 * the diff's red and green do not apply, and a brand tint over code reads as
 * a selection. Where rows need grouping, it is the neutral muted band.
 *
 * Three ways to compare, as tabs to pick from, and the single view they are
 * all built on:
 *
 *  - Unified: one document. Shared lines print once, muted; a value that
 *    differs prints once per language, labelled en / ar in the gutter where
 *    the diff has − / +.
 *  - Table: no code at all. Every value is a row under its section; a value
 *    both share spans both columns, a value that differs splits.
 *  - Side by side: the two documents aligned key by key, identical rows
 *    muted, differing rows marked at the edge.
 *  - Single: one value, line numbers, folds, Copy.
 *
 * Short arrays of plain values print on one line, as a person would write
 * them, so a whitelist is one row rather than five. Arabic strings sit in
 * `<bdi>`, so a right-to-left value in a left-to-right line keeps its quotes.
 */

type Json = null | boolean | number | string | Json[] | { [key: string]: Json }
type Container = Json[] | { [key: string]: Json }

/* The platform's global settings, per language, as far as the admin page
   shows them. */
const ENGLISH: Json = {
  agentName: "Sara",
  allowInterruptions: true,
  backChannel: { type: "word", value: 0.6, whitelist: ["I see", "ok"] },
  maxDurationEndCallMessage: null,
  models: {
    fallback: {
      models: [
        { model: "long", provider: "google", region: "eu" },
        { model: "gpt-4o-transcribe", provider: "openai" },
      ],
      type: "enable",
    },
    llm: {
      model: "flash-lite-3.1",
      provider: "gemini",
      region: "europe-west3",
    },
    stt: { provider: "aws", region: "eu-central-1" },
    tts: {
      arabicVoiceId: "DJR3iLTFoK76RjR7KFUy",
      model: "eleven_flash_v2_5",
      provider: "11labs",
      speed: 1,
    },
  },
  voice: { createdAt: "2025-12-10T19:11:38.607826Z", displayName: "Sara" },
}

const ARABIC: Json = {
  agentName: "عبدالله",
  allowInterruptions: true,
  backChannel: { type: "word", value: 0.6, whitelist: ["حاضر", "طيب", "تمام"] },
  maxDurationEndCallMessage: null,
  models: {
    fallback: {
      models: [
        { model: "long", provider: "google", region: "eu" },
        { provider: "azure", region: "germanywestcentral" },
      ],
      type: "enable",
    },
    llm: {
      model: "flash-lite-3.1",
      provider: "gemini",
      region: "europe-west3",
    },
    stt: { provider: "aws", region: "eu-central-1" },
    tts: { provider: "groq", voice: "abdullah" },
  },
  voice: { createdAt: "2026-04-12T10:35:46.739089Z", displayName: "Abdullah" },
}

type Side = { label: string; code: string; value: Json }

const LEFT: Side = { label: "English", code: "en", value: ENGLISH }
const RIGHT: Side = { label: "Arabic", code: "ar", value: ARABIC }

const VIEWS = [
  { id: "unified", label: "Unified" },
  { id: "table", label: "Table" },
  { id: "side-by-side", label: "Side by side" },
  { id: "single", label: "Single" },
]

export function JsonViewPreview() {
  const [view, setView] = React.useState("unified")
  const [only, setOnly] = React.useState(false)
  const compare = { left: LEFT, right: RIGHT, only }

  return (
    <SecondaryTabs items={VIEWS} onValueChange={setView} value={view}>
      <TabsContent value="unified">
        <CompareBar onOnly={setOnly} only={only}>
          <JsonUnified {...compare} />
        </CompareBar>
      </TabsContent>
      <TabsContent value="table">
        <CompareBar onOnly={setOnly} only={only}>
          <JsonTable {...compare} />
        </CompareBar>
      </TabsContent>
      <TabsContent value="side-by-side">
        <CompareBar onOnly={setOnly} only={only}>
          <JsonSideBySide {...compare} />
        </CompareBar>
      </TabsContent>
      <TabsContent value="single">
        <JsonView value={ENGLISH} />
      </TabsContent>
    </SecondaryTabs>
  )
}

/* ------------------------------------------------------------------ model */

/** Short enough to write on one line, and nothing nested inside. */
const INLINE_MAX = 48

function isContainer(value: Json | undefined): value is Container {
  return typeof value === "object" && value !== null
}

/** A value printed across several lines, with a fold. */
function isBranch(value: Json | undefined): value is Container {
  return (
    isContainer(value) &&
    !(
      Array.isArray(value) &&
      value.every((item) => !isContainer(item)) &&
      JSON.stringify(value).length <= INLINE_MAX
    )
  )
}

function members(value: Container): [string, Json][] {
  return Array.isArray(value)
    ? value.map((item, index) => [String(index), item])
    : Object.entries(value)
}

function same(a: Json | undefined, b: Json | undefined) {
  return JSON.stringify(a) === JSON.stringify(b)
}

function brackets(value: Container) {
  return Array.isArray(value) ? (["[", "]"] as const) : (["{", "}"] as const)
}

/** Both sides' keys, in the first side's order, then the second's extras. */
function union(a: Container, b: Container) {
  const left = new Map(members(a))
  const right = new Map(members(b))
  return {
    keys: [...new Set([...left.keys(), ...right.keys()])],
    left,
    right,
  }
}

/** How many values differ, counted at the printed leaves. */
function countDifferences(a: Json | undefined, b: Json | undefined): number {
  if (isBranch(a) && isBranch(b) && Array.isArray(a) === Array.isArray(b)) {
    const { keys, left, right } = union(a, b)
    return keys.reduce(
      (sum, key) => sum + countDifferences(left.get(key), right.get(key)),
      0,
    )
  }
  return same(a, b) ? 0 : 1
}

type Line = {
  id: string
  /** Where the line sits in the value — also what folds it. */
  path: string
  depth: number
  /** The key, on an object's members. Array items and the root have none. */
  label?: string
  kind: "open" | "close" | "leaf" | "folded"
  value?: Json
  bracket?: string
  /** How many members a folded branch is hiding. */
  count?: number
  comma: boolean
  /** On a compared line that belongs to one side only. */
  side?: "left" | "right"
}

function folded(
  value: Container,
  path: string,
  depth: number,
  label: string | undefined,
  comma: boolean,
): Line {
  return {
    id: path,
    path,
    depth,
    label,
    kind: "folded",
    bracket: brackets(value)[0],
    count: members(value).length,
    comma,
  }
}

/** One value as lines. */
function toLines(
  value: Json,
  folds: Set<string>,
  path = "$",
  depth = 0,
  label?: string,
  comma = false,
): Line[] {
  if (!isBranch(value)) {
    return [{ id: path, path, depth, label, kind: "leaf", value, comma }]
  }
  if (folds.has(path)) return [folded(value, path, depth, label, comma)]

  const [open, close] = brackets(value)
  const list = members(value)
  return [
    { id: path, path, depth, label, kind: "open", bracket: open, comma: false },
    ...list.flatMap(([key, item], index) =>
      toLines(
        item,
        folds,
        `${path}.${key}`,
        depth + 1,
        Array.isArray(value) ? undefined : key,
        index < list.length - 1,
      ),
    ),
    { id: `${path}:close`, path, depth, kind: "close", bracket: close, comma },
  ]
}

type CompareOptions = { folds: Set<string>; only: boolean }

/**
 * Two values as one document: a shared line once, a differing value once per
 * side. Branches both sides have are walked together, so a difference deep in
 * `models` does not reprint the rest of `models`.
 */
function toUnified(
  a: Json | undefined,
  b: Json | undefined,
  options: CompareOptions,
  path = "$",
  depth = 0,
  label?: string,
  comma = false,
): Line[] {
  const identical = same(a, b)

  if (isBranch(a) && isBranch(b) && Array.isArray(a) === Array.isArray(b)) {
    if (options.folds.has(path) || (options.only && identical)) {
      return [folded(a, path, depth, label, comma)]
    }
    const [open, close] = brackets(a)
    const { keys, left, right } = union(a, b)
    return [
      {
        id: path,
        path,
        depth,
        label,
        kind: "open",
        bracket: open,
        comma: false,
      },
      ...keys.flatMap((key, index) =>
        toUnified(
          left.get(key),
          right.get(key),
          options,
          `${path}.${key}`,
          depth + 1,
          Array.isArray(a) ? undefined : key,
          index < keys.length - 1,
        ),
      ),
      {
        id: `${path}:close`,
        path,
        depth,
        kind: "close",
        bracket: close,
        comma,
      },
    ]
  }

  if (identical) {
    return options.only
      ? []
      : [{ id: path, path, depth, label, kind: "leaf", value: a, comma }]
  }

  const one = (value: Json, side: "left" | "right"): Line => ({
    ...(isBranch(value)
      ? folded(value, path, depth, label, comma)
      : { id: path, path, depth, label, kind: "leaf" as const, value, comma }),
    id: `${path}@${side}`,
    side,
  })
  return [
    ...(a === undefined ? [] : [one(a, "left")]),
    ...(b === undefined ? [] : [one(b, "right")]),
  ]
}

type Row = {
  id: string
  left: Line | null
  right: Line | null
  differs: boolean
}

/** The unified lines laid out in two halves, one row per key. */
function toRows(
  a: Json | undefined,
  b: Json | undefined,
  options: CompareOptions,
): Row[] {
  return toUnified(a, b, options).reduce<Row[]>((rows, line) => {
    if (!line.side) {
      rows.push({ id: line.id, left: line, right: line, differs: false })
      return rows
    }
    /* The right half of a differing value joins the row its left half
       opened, so the two sit level. */
    const last = rows[rows.length - 1]
    if (line.side === "right" && last?.id === `${line.path}@left`) {
      last.right = line
      return rows
    }
    rows.push({
      id: line.id,
      left: line.side === "left" ? line : null,
      right: line.side === "right" ? line : null,
      differs: true,
    })
    return rows
  }, [])
}

function childPath(prefix: string, key: string, inArray: boolean) {
  if (inArray) return `${prefix}[${key}]`
  return prefix ? `${prefix}.${key}` : key
}

/** Every printed leaf of one value, by its path. */
function flatten(value: Json, prefix = "", out = new Map<string, Json>()) {
  if (!isBranch(value)) {
    out.set(prefix, value)
    return out
  }
  for (const [key, item] of members(value)) {
    flatten(item, childPath(prefix, key, Array.isArray(value)), out)
  }
  return out
}

type TableRowData = { path: string; a: Json | undefined; b: Json | undefined }

/**
 * Both values' leaves, walked together so a key only one side has lands
 * beside its siblings rather than at the end of the section.
 */
function pairLeaves(
  a: Json | undefined,
  b: Json | undefined,
  prefix = "",
): TableRowData[] {
  if (isBranch(a) && isBranch(b) && Array.isArray(a) === Array.isArray(b)) {
    const { keys, left, right } = union(a, b)
    return keys.flatMap((key) =>
      pairLeaves(
        left.get(key),
        right.get(key),
        childPath(prefix, key, Array.isArray(a)),
      ),
    )
  }
  if (!isBranch(a) && !isBranch(b)) return [{ path: prefix, a, b }]

  /* A branch against a plain value or nothing: each side's own leaves. */
  const from = a === undefined ? new Map<string, Json>() : flatten(a, prefix)
  const to = b === undefined ? new Map<string, Json>() : flatten(b, prefix)
  return [...new Set([...from.keys(), ...to.keys()])].map((path) => ({
    path,
    a: from.get(path),
    b: to.get(path),
  }))
}

/* ------------------------------------------------------------------ parts */

function useFolds() {
  const [folds, setFolds] = React.useState<Set<string>>(() => new Set())
  const toggle = (path: string) =>
    setFolds((current) => {
      const next = new Set(current)
      if (next.has(path)) next.delete(path)
      else next.add(path)
      return next
    })
  return { folds, toggle }
}

function useCopy() {
  const [copied, setCopied] = React.useState<string | null>(null)
  const copy = async (id: string, value: Json) => {
    try {
      await navigator.clipboard.writeText(JSON.stringify(value, null, 2))
      setCopied(id)
      window.setTimeout(() => setCopied(null), 1500)
    } catch {
      toast.error("Could not copy — select the text instead")
    }
  }
  return { copied, copy }
}

/** A plain value or a one-line array, as JSON writes it. */
function Value({ value }: { value: Json | undefined }) {
  if (typeof value === "string") return <bdi>&quot;{value}&quot;</bdi>
  if (Array.isArray(value)) {
    return (
      <>
        [
        {value.map((item, index) => (
          <React.Fragment key={index}>
            {index > 0 ? ", " : null}
            <Value value={item} />
          </React.Fragment>
        ))}
        ]
      </>
    )
  }
  return <>{String(value)}</>
}

/**
 * The line itself. Keys and punctuation are muted and the value is not,
 * because the value is what you read; `muted` drops the value too, for a
 * line both sides share.
 */
function Code({ line, muted = false }: { line: Line; muted?: boolean }) {
  return (
    <span
      className="min-w-0 truncate whitespace-pre text-muted-foreground"
      /* Two characters a level, as JSON.stringify indents. */
      style={{ paddingInlineStart: `${line.depth * 2}ch` }}
    >
      {line.label !== undefined && line.kind !== "close" ? (
        <>&quot;{line.label}&quot;: </>
      ) : null}
      {line.kind === "leaf" ? (
        <span className={muted ? undefined : "text-foreground"}>
          <Value value={line.value} />
        </span>
      ) : line.kind === "folded" ? (
        <>
          {line.bracket}
          <span className="mx-1 rounded-sm bg-muted px-1">
            {line.count} {line.bracket === "[" ? "items" : "keys"}
          </span>
          {line.bracket === "[" ? "]" : "}"}
        </>
      ) : (
        line.bracket
      )}
      {line.comma ? "," : null}
    </span>
  )
}

/** The fold toggle, on an opening line or a folded one; a spacer elsewhere. */
function Fold({
  line,
  onToggle,
}: {
  line: Line | null
  onToggle: (path: string) => void
}) {
  if (!line || line.side || (line.kind !== "open" && line.kind !== "folded")) {
    return <span aria-hidden className="w-6 shrink-0" />
  }
  const open = line.kind === "open"
  return (
    <Button
